<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientDefaultAcrValuesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDefaultAcrValuesAccessor trait.
 *
 * Covers null default, string/VO assignment via withDefaultAcrValues,
 * getDefaultAcrValues/defaultAcrValues accessors, and isDefaultAcrValuesChanged with/without original.
 */
class TrustedClientDefaultAcrValuesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDefaultAcrValues creates a new instance with the DefaultAcrValues set
     * from a string value, and getDefaultAcrValues returns the primitive string.
     */
    public function testWithDefaultAcrValuesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultAcrValuesAccessorUnitTest();

        // Act
        $result = $holder->withDefaultAcrValues('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDefaultAcrValues());
    }
    /**
     * Asserts that withdefaultAcrValues has access to the value object
     * from a string value, and getDefaultAcrValues returns the primitive string.
     */
    public function testWithDefaultAcrValuesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultAcrValuesAccessorUnitTest();

        // Act
        $result = $holder->withDefaultAcrValues('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->defaultAcrValues()->value());
    }
    public function testChangedDefaultAcrValues(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultAcrValuesAccessorUnitTest();
        $original = $holder->withDefaultAcrValues('one');
        $same = $holder->withDefaultAcrValues('one');
        $modified = $holder->withDefaultAcrValues('other');

        // Act
        $unchanged = $holder->isDefaultAcrValuesChanged();
        $withSame = $original->isDefaultAcrValuesChanged($same);
        $withDiferent = $original->isDefaultAcrValuesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientDefaultAcrValuesAccessorUnitTest
{
    use TrustedClientDefaultAcrValuesAccessor;
}
